# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    fields = []
    i, n = 0, len(payload)
    while True:
        chars = []
        if i < n and payload[i] == '"':
            i += 1
            while True:
                if i == n:
                    return {"error": n}
                if payload[i] != '"':
                    chars.append(payload[i])
                    i += 1
                elif i + 1 < n and payload[i + 1] == '"':
                    chars.append('"')
                    i += 2
                else:
                    i += 1
                    break
            if i < n and payload[i] != ',':
                return {"error": i}
        else:
            while i < n and payload[i] != ',':
                if payload[i] in '\r\n"':
                    return {"error": i}
                chars.append(payload[i])
                i += 1
        fields.append(''.join(chars))
        if i == n:
            return {"fields": fields}
        i += 1

